    Bug 1742904 - Fix moving of contacts via the editContactPanel.js. r=aleca

    Fixes a logic error in the WebExtension addressbook API, ensuring that
    we actually use the available cache when it exists.

    When moving cards between address books, the moved card will now get a new
    UID, to not throw off remote servers when receiving "old" cards again, and
    also to prevent cards being removed from any UID based cache (since we first
    add the new card before deleting the old one, which also removes the new one).

    Differential Revision: https://phabricator.services.mozilla.com/D160463

diff --git a/mail/base/content/editContactPanel.js b/mail/base/content/editContactPanel.js
index 549b039c136..65571c32e23 100644
--- a/mail/base/content/editContactPanel.js
+++ b/mail/base/content/editContactPanel.js
@@ -235,8 +235,8 @@ var editContactInlineUI = {
     } else {
       // We changed address books for the card.

-      // Add it to the chosen address book...
-      this._cardDetails.book.addCard(this._cardDetails.card);
+      // Add it to the chosen address book (with a new UID) ...
+      this._cardDetails.book.dropCard(this._cardDetails.card, true);

       // ...and delete it from the old place.
       originalBook.deleteCards([this._cardDetails.card]);
